--

CREATE TABLE public.warehouses_stockmovement (
    id bigint NOT NULL,
    movement_type character varying(10) NOT NULL,
    quantity integer NOT NULL,
    previous_quantity integer NOT NULL,
    new_quantity integer NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by_id bigint,
    stock_id bigint NOT NULL,
    CONSTRAINT warehouses_stockmovement_new_quantity_check CHECK ((new_quantity >= 0)),
    CONSTRAINT warehouses_stockmovement_previous_quantity_check CHECK ((previous_quantity >= 0))
);


